import {
  createPaymentQueryResult,
  createPaymentResult,
  createRefundQueryResult,
  createRefundResult,
  type NotificationVerificationResult,
  type PaymentStatus,
  type RefundStatus,
} from "@bd-pay-kit/shared";
import { SSLCOMMERZ_GATEWAY_NAME } from "../constants.js";
import type {
  SSLCommerzCreatePaymentResult,
  SSLCommerzInitPaymentInput,
  SSLCommerzInitPaymentResult,
  SSLCommerzNotificationApiResult,
  SSLCommerzNotificationPayload,
  SSLCommerzPaymentApiResult,
  SSLCommerzPaymentLookupResponse,
  SSLCommerzPaymentQueryResult,
  SSLCommerzRefundApiResult,
  SSLCommerzRefundQueryResponse,
  SSLCommerzRefundQueryResult,
  SSLCommerzRefundResponse,
  SSLCommerzSessionResponse,
  SSLCommerzTransactionQueryResponse,
  SSLCommerzValidatePaymentResult,
} from "../types.js";

export function mapSSLCommerzInitPaymentResult<TRaw extends SSLCommerzSessionResponse>(
  raw: TRaw,
  input: Pick<
    SSLCommerzInitPaymentInput,
    "totalAmount" | "currency" | "transactionId" | "successUrl" | "failUrl" | "cancelUrl"
  >,
): SSLCommerzInitPaymentResult<TRaw> {
  return createPaymentResult(
    SSLCOMMERZ_GATEWAY_NAME,
    {
      gateway: SSLCOMMERZ_GATEWAY_NAME,
      status: "requires_action",
      money: {
        amount: input.totalAmount,
        currency: input.currency,
      },
      references: {
        merchantInvoiceNumber: input.transactionId,
        providerSessionId: raw.sessionkey,
      },
      redirect: raw.GatewayPageURL
        ? {
            url: raw.GatewayPageURL,
            method: "GET",
            successCallbackUrl: input.successUrl,
            failureCallbackUrl: input.failUrl,
            cancelCallbackUrl: input.cancelUrl,
          }
        : undefined,
      message: raw.status,
      metadata: compactMetadata({
        directPaymentUrl: raw.directPaymentURL,
        storeBanner: raw.storeBanner,
        storeLogo: raw.storeLogo,
        availableGatewayCategories: raw.gw ? String(Object.keys(raw.gw).length) : undefined,
        directPayEnabled: toOptionalString(raw.is_direct_pay_enable),
      }),
    },
    raw,
  );
}

export function mapSSLCommerzCreatePaymentResult<TRaw extends SSLCommerzSessionResponse>(
  raw: TRaw,
  input: Pick<
    SSLCommerzInitPaymentInput,
    "totalAmount" | "currency" | "transactionId" | "successUrl" | "failUrl" | "cancelUrl"
  >,
): SSLCommerzCreatePaymentResult<TRaw> {
  return mapSSLCommerzInitPaymentResult(raw, input);
}

export function mapSSLCommerzValidatePaymentResult<
  TRaw extends SSLCommerzPaymentLookupResponse,
>(
  raw: TRaw,
): SSLCommerzValidatePaymentResult<TRaw> {
  return createPaymentResult(SSLCOMMERZ_GATEWAY_NAME, createNormalizedPayment(raw), raw);
}

export function mapSSLCommerzPaymentResult<TRaw extends SSLCommerzPaymentLookupResponse>(
  raw: TRaw,
): SSLCommerzPaymentApiResult<TRaw> {
  return mapSSLCommerzValidatePaymentResult(raw);
}

export function mapSSLCommerzQueryBySessionResult<
  TRaw extends SSLCommerzPaymentLookupResponse,
>(
  raw: TRaw,
): SSLCommerzPaymentQueryResult<TRaw> {
  const normalized = createNormalizedPayment(raw);

  return createPaymentQueryResult(
    SSLCOMMERZ_GATEWAY_NAME,
    {
      ...normalized,
      queriedAt: raw.validated_on ?? raw.tran_date,
    },
    raw,
  );
}

export function mapSSLCommerzQueryByTransactionResult<
  TRaw extends SSLCommerzTransactionQueryResponse,
>(
  raw: TRaw,
  selected: SSLCommerzPaymentLookupResponse,
): SSLCommerzPaymentQueryResult<TRaw> {
  const normalized = createNormalizedPayment(selected);

  return createPaymentQueryResult(
    SSLCOMMERZ_GATEWAY_NAME,
    {
      ...normalized,
      queriedAt: selected.validated_on ?? selected.tran_date,
      metadata: compactMetadata({
        ...(normalized.metadata ?? {}),
        matchedTransactions: toOptionalString(raw.no_of_trans_found),
      }),
    },
    raw,
  );
}

export function mapSSLCommerzTransactionQueryResult<
  TRaw extends SSLCommerzTransactionQueryResponse,
>(
  raw: TRaw,
  selected: SSLCommerzPaymentLookupResponse,
): SSLCommerzPaymentQueryResult<TRaw> {
  return mapSSLCommerzQueryByTransactionResult(raw, selected);
}

export function mapSSLCommerzInitiateRefundResult<TRaw extends SSLCommerzRefundResponse>(
  raw: TRaw,
): SSLCommerzRefundApiResult<TRaw> {
  return createRefundResult(
    SSLCOMMERZ_GATEWAY_NAME,
    {
      gateway: SSLCOMMERZ_GATEWAY_NAME,
      status: mapSSLCommerzRefundStatus(raw.status, "initiate"),
      money: {
        amount: "0",
        currency: "BDT",
      },
      references: {
        merchantInvoiceNumber: raw.trans_id ?? raw.tran_id,
        providerTransactionId: raw.bank_tran_id,
        providerRefundId: raw.refund_ref_id,
      },
      message: raw.status,
      metadata: compactMetadata({
        apiConnect: raw.APIConnect,
        errorReason: raw.errorReason,
      }),
    },
    raw,
  );
}

export function mapSSLCommerzRefundResult<TRaw extends SSLCommerzRefundResponse>(
  raw: TRaw,
): SSLCommerzRefundApiResult<TRaw> {
  return mapSSLCommerzInitiateRefundResult(raw);
}

export function mapSSLCommerzRefundQueryResult<TRaw extends SSLCommerzRefundQueryResponse>(
  raw: TRaw,
): SSLCommerzRefundQueryResult<TRaw> {
  return createRefundQueryResult(
    SSLCOMMERZ_GATEWAY_NAME,
    {
      gateway: SSLCOMMERZ_GATEWAY_NAME,
      status: mapSSLCommerzRefundStatus(raw.status, "query"),
      money: {
        amount: "0",
        currency: "BDT",
      },
      references: {
        merchantInvoiceNumber: raw.trans_id ?? raw.tran_id,
        providerTransactionId: raw.bank_tran_id,
        providerRefundId: raw.refund_ref_id,
      },
      message: raw.status,
      requestedAt: raw.initiated_on,
      completedAt: raw.refunded_on,
      queriedAt: raw.refunded_on ?? raw.initiated_on,
      metadata: compactMetadata({
        apiConnect: raw.APIConnect,
        errorReason: raw.errorReason,
      }),
    },
    raw,
  );
}

export function mapSSLCommerzNotificationResult<
  TRaw extends SSLCommerzNotificationPayload,
>(
  raw: TRaw,
  isVerified: boolean,
  message: string,
): SSLCommerzNotificationApiResult<TRaw> {
  const normalized: NotificationVerificationResult = {
    gateway: SSLCOMMERZ_GATEWAY_NAME,
    isVerified,
    kind: "payment",
    references: {
      merchantInvoiceNumber: toOptionalString(raw.tran_id),
      providerTransactionId: toOptionalString(raw.bank_tran_id),
      providerValidationId: toOptionalString(raw.val_id),
    },
    message,
    receivedAt: toOptionalString(raw.tran_date),
  };

  return {
    gateway: SSLCOMMERZ_GATEWAY_NAME,
    normalized,
    raw,
  };
}

function createNormalizedPayment(
  raw: SSLCommerzPaymentLookupResponse,
): SSLCommerzPaymentApiResult<SSLCommerzPaymentLookupResponse>["normalized"] {
  return {
    gateway: SSLCOMMERZ_GATEWAY_NAME,
    status: mapSSLCommerzPaymentStatus(raw.status),
    money: {
      amount: toOptionalString(raw.amount) ?? "0",
      currency: raw.currency ?? raw.currency_type ?? "BDT",
    },
    references: {
      merchantInvoiceNumber: raw.tran_id,
      providerSessionId: raw.sessionkey,
      providerTransactionId: raw.bank_tran_id,
      providerValidationId: raw.val_id,
    },
    message: raw.status ?? raw.error,
    createdAt: raw.tran_date,
    completedAt: raw.validated_on ?? raw.tran_date,
    metadata: compactMetadata({
      apiConnect: raw.APIConnect,
      storeAmount: toOptionalString(raw.store_amount),
      cardType: raw.card_type,
      cardBrand: raw.card_brand,
      cardIssuer: raw.card_issuer,
      cardIssuerCountry: raw.card_issuer_country,
      cardIssuerCountryCode: raw.card_issuer_country_code,
      riskLevel: toOptionalString(raw.risk_level),
      riskTitle: raw.risk_title,
      gatewayVersion: raw.gw_version,
      emiInstallment: toOptionalString(raw.emi_instalment),
      emiAmount: toOptionalString(raw.emi_amount),
      emiDescription: raw.emi_description,
      emiIssuer: raw.emi_issuer,
    }),
  };
}

function mapSSLCommerzPaymentStatus(status: string | undefined): PaymentStatus {
  switch ((status ?? "").toUpperCase()) {
    case "VALID":
    case "VALIDATED":
      return "succeeded";
    case "PENDING":
    case "PROCESSING":
      return "processing";
    case "FAILED":
      return "failed";
    case "CANCELLED":
    case "CANCELED":
    case "UNATTEMPTED":
      return "canceled";
    case "EXPIRED":
      return "expired";
    default:
      return "pending";
  }
}

function mapSSLCommerzRefundStatus(
  status: string | undefined,
  stage: "initiate" | "query",
): RefundStatus {
  switch ((status ?? "").toLowerCase()) {
    case "success":
      return stage === "initiate" ? "processing" : "succeeded";
    case "processing":
      return "processing";
    case "refunded":
      return "succeeded";
    case "cancelled":
    case "canceled":
      return "canceled";
    case "failed":
      return "failed";
    default:
      return "pending";
  }
}

function compactMetadata(
  metadata: Record<string, string | undefined>,
): Readonly<Record<string, string>> | undefined {
  const entries = Object.entries(metadata).filter(([, value]) => value !== undefined);

  if (entries.length === 0) {
    return undefined;
  }

  return Object.freeze(Object.fromEntries(entries) as Record<string, string>);
}

function toOptionalString(value: string | number | undefined): string | undefined {
  if (value === undefined) {
    return undefined;
  }

  return String(value);
}