import { createPaymentResult } from "@bd-pay-kit/shared";
import type { GatewayEnvironment } from "@bd-pay-kit/core";
import {
  ROCKET_GATEWAY_NAME,
  ROCKET_INFERRED_MANUAL_FLOWS,
  ROCKET_MANUAL_PAYMENT_MESSAGE,
  ROCKET_OFFICIAL_SOURCES,
  ROCKET_OPERATIONAL_FLOW,
  ROCKET_PHASE1_CAPABILITIES,
  ROCKET_PHASE1_LIMITATIONS,
  ROCKET_PHASE1_NOTES,
  ROCKET_UNSUPPORTED_OR_UNDOCUMENTED_FLOWS,
  ROCKET_UNVERIFIED_NOTIFICATION_MESSAGE,
  ROCKET_VERIFIED_OFFICIAL_FLOWS,
} from "./constants.js";
import type {
  RocketCreatePaymentInput,
  RocketMerchantPaymentGuide,
  RocketManualPaymentRecord,
  RocketNotificationApiResult,
  RocketNotificationPayload,
  RocketPaymentApiResult,
} from "./types.js";

export function mapRocketMerchantPaymentGuide(
  environment: GatewayEnvironment,
): RocketMerchantPaymentGuide {
  return {
    gateway: ROCKET_GATEWAY_NAME,
    environment,
    mode: "manual",
    isDirectBackendApiSupported: false,
    requiresMerchantMobileInitiation: true,
    requiresCustomerSmsOrIvrConfirmation: true,
    capabilities: ROCKET_PHASE1_CAPABILITIES,
    verifiedOfficialFlows: ROCKET_VERIFIED_OFFICIAL_FLOWS,
    inferredManualFlows: ROCKET_INFERRED_MANUAL_FLOWS,
    unsupportedOrUndocumentedFlows: ROCKET_UNSUPPORTED_OR_UNDOCUMENTED_FLOWS,
    operationalFlow: ROCKET_OPERATIONAL_FLOW,
    notes: ROCKET_PHASE1_NOTES,
    limitations: ROCKET_PHASE1_LIMITATIONS,
    raw: {
      sources: ROCKET_OFFICIAL_SOURCES,
    },
  };
}

export function mapRocketManualPaymentResult(
  environment: GatewayEnvironment,
  input: RocketCreatePaymentInput,
): RocketPaymentApiResult<RocketManualPaymentRecord> {
  const raw: RocketManualPaymentRecord = {
    mode: "manual",
    environment,
    merchantInput: input,
    requiresMerchantMobileInitiation: true,
    requiresCustomerSmsOrIvrConfirmation: true,
    operationalFlow: ROCKET_OPERATIONAL_FLOW,
    verifiedOfficialFlows: ROCKET_VERIFIED_OFFICIAL_FLOWS,
    inferredManualFlows: ROCKET_INFERRED_MANUAL_FLOWS,
    unsupportedOrUndocumentedFlows: ROCKET_UNSUPPORTED_OR_UNDOCUMENTED_FLOWS,
    sources: ROCKET_OFFICIAL_SOURCES,
  };

  return createPaymentResult(
    ROCKET_GATEWAY_NAME,
    {
      gateway: ROCKET_GATEWAY_NAME,
      status: "requires_action",
      money: {
        amount: input.amount,
        currency: input.currency,
      },
      references: {
        merchantInvoiceNumber: input.merchantInvoiceNumber,
      },
      message: ROCKET_MANUAL_PAYMENT_MESSAGE,
      metadata: {
        flowMode: "manual",
        merchantMobileInitiationRequired: "true",
        customerConfirmation: "sms_or_ivr",
      },
    },
    raw,
  );
}

export function mapRocketNotificationVerificationResult<
  TRaw extends RocketNotificationPayload,
>(
  payload: TRaw,
  message = ROCKET_UNVERIFIED_NOTIFICATION_MESSAGE,
): RocketNotificationApiResult<TRaw> {
  return {
    gateway: ROCKET_GATEWAY_NAME,
    normalized: {
      gateway: ROCKET_GATEWAY_NAME,
      isVerified: false,
      kind: "unknown",
      message,
    },
    raw: payload,
  };
}