import { ValidationError, omitUndefined } from "@bd-pay-kit/core";
import type { SSLCommerzInitiateRefundInput } from "../types.js";

export function buildInitiateRefundQuery(
  input: SSLCommerzInitiateRefundInput,
  credentials: { storeId: string; storePassword: string },
): Record<string, string | number> {
  assertRequiredString(input.bankTransactionId, "bankTransactionId");
  assertRequiredString(input.refundTransactionId, "refundTransactionId");
  assertRequiredString(input.refundAmount, "refundAmount");
  assertRequiredString(input.refundRemarks, "refundRemarks");

  return omitUndefined({
    bank_tran_id: input.bankTransactionId,
    refund_trans_id: input.refundTransactionId,
    refund_amount: input.refundAmount,
    refund_remarks: input.refundRemarks,
    refe_id: input.referenceId,
    store_id: credentials.storeId,
    store_passwd: credentials.storePassword,
    v: 1,
    format: "json",
  });
}

function assertRequiredString(value: string | undefined, fieldName: string): void {
  if (!value || value.trim().length === 0) {
    throw new ValidationError(`${fieldName} is required.`);
  }
}