import { BkashClient } from "@bd-pay-kit/bkash";
import { NagadClient } from "@bd-pay-kit/nagad";
import { RocketClient } from "@bd-pay-kit/rocket";
import { SSLCommerzClient } from "@bd-pay-kit/sslcommerz";
import type {
  ImplementedGatewayName,
  SDKGatewayClientMap,
  SDKGatewayConfigMap,
} from "./gateways.js";

export function createGateway(
  gateway: "bkash",
  config: SDKGatewayConfigMap["bkash"],
): SDKGatewayClientMap["bkash"];
export function createGateway(
  gateway: "sslcommerz",
  config: SDKGatewayConfigMap["sslcommerz"],
): SDKGatewayClientMap["sslcommerz"];
export function createGateway(
  gateway: "nagad",
  config: SDKGatewayConfigMap["nagad"],
): SDKGatewayClientMap["nagad"];
export function createGateway(
  gateway: "rocket",
  config: SDKGatewayConfigMap["rocket"],
): SDKGatewayClientMap["rocket"];
export function createGateway<TGateway extends ImplementedGatewayName>(
  gateway: TGateway,
  config: SDKGatewayConfigMap[TGateway],
): SDKGatewayClientMap[TGateway];
export function createGateway(
  gateway: ImplementedGatewayName,
  config: SDKGatewayConfigMap[ImplementedGatewayName],
): SDKGatewayClientMap[ImplementedGatewayName] {
  switch (gateway) {
    case "bkash":
      return new BkashClient(config as SDKGatewayConfigMap["bkash"]);
    case "sslcommerz":
      return new SSLCommerzClient(config as SDKGatewayConfigMap["sslcommerz"]);
    case "nagad":
      return new NagadClient(config as SDKGatewayConfigMap["nagad"]);
    case "rocket":
      return new RocketClient(config as SDKGatewayConfigMap["rocket"]);
    default:
      return assertNever(gateway);
  }
}

function assertNever(value: never): never {
  throw new Error(`Unsupported gateway: ${String(value)}`);
}