import { ConfigurationError } from "@bd-pay-kit/core";
import {
  SSLCOMMERZ_DEFAULT_TIMEOUT_MS,
  resolveSSLCommerzBaseUrl,
} from "./constants.js";
import type { SSLCommerzConfig } from "./types.js";

export interface ResolvedSSLCommerzConfig {
  readonly baseUrl: string;
  readonly timeoutMs: number;
  readonly storeId: string;
  readonly storePassword: string;
}

export function resolveSSLCommerzConfig(
  config: SSLCommerzConfig,
): ResolvedSSLCommerzConfig {
  const baseUrl = resolveSSLCommerzBaseUrl(config.environment, config.baseUrl);
  const timeoutMs = config.timeoutMs ?? SSLCOMMERZ_DEFAULT_TIMEOUT_MS;

  assertConfigString(config.storeId, "storeId");
  assertConfigString(config.storePassword, "storePassword");

  if (!baseUrl) {
    throw new ConfigurationError("SSLCommerz baseUrl could not be resolved.");
  }

  return {
    baseUrl,
    timeoutMs,
    storeId: config.storeId,
    storePassword: config.storePassword,
  };
}

function assertConfigString(value: string | undefined, fieldName: string): asserts value is string {
  if (!value || value.trim().length === 0) {
    throw new ConfigurationError(`${fieldName} is required.`);
  }
}