export interface PaymentErrorContext {
  gateway?: string;
  operation?: string;
  requestId?: string;
  providerCode?: string;
  statusCode?: number;
  details?: Readonly<Record<string, unknown>>;
}

export interface PaymentErrorOptions {
  code?: string;
  context?: PaymentErrorContext;
  cause?: unknown;
}

export class PaymentError extends Error {
  readonly code: string;
  readonly context: PaymentErrorContext;

  constructor(message: string, options: PaymentErrorOptions = {}) {
    super(message, options.cause !== undefined ? { cause: options.cause } : undefined);

    this.name = new.target.name;
    this.code = options.code ?? "PAYMENT_ERROR";
    this.context = options.context ?? {};

    Object.setPrototypeOf(this, new.target.prototype);
  }
}

export class ValidationError extends PaymentError {
  constructor(message: string, options: PaymentErrorOptions = {}) {
    super(message, { ...options, code: options.code ?? "VALIDATION_ERROR" });
  }
}

export class ConfigurationError extends ValidationError {
  constructor(message: string, options: PaymentErrorOptions = {}) {
    super(message, { ...options, code: options.code ?? "CONFIGURATION_ERROR" });
  }
}

