import { BaseGateway, PaymentError } from "@bd-pay-kit/core";
import {
  ROCKET_GATEWAY_NAME,
  ROCKET_PENDING_RUNTIME_ERROR_CODE,
  createRocketDescriptor,
  createRocketPendingRuntimeMessage,
} from "./constants.js";
import {
  validateRocketConfig,
  validateRocketCreatePaymentInput,
} from "./config.js";
import {
  mapRocketManualPaymentResult,
  mapRocketMerchantPaymentGuide,
  mapRocketNotificationVerificationResult,
} from "./mappers.js";
import type {
  RocketConfig,
  RocketCreatePaymentInput,
  RocketGatewayDescriptor,
  RocketMerchantPaymentGuide,
  RocketNotificationApiResult,
  RocketNotificationPayload,
  RocketPaymentApiResult,
  RocketPaymentQueryApiResult,
  RocketQueryPaymentInput,
  RocketRuntimeOperationName,
  RocketVerifyPaymentInput,
} from "./types.js";

export class RocketClient extends BaseGateway<typeof ROCKET_GATEWAY_NAME, RocketConfig> {
  readonly descriptor: RocketGatewayDescriptor;

  constructor(config: RocketConfig) {
    validateRocketConfig(config);
    super(ROCKET_GATEWAY_NAME, config);
    this.descriptor = createRocketDescriptor(this.environment);
  }

  describeMerchantPayment(): RocketMerchantPaymentGuide {
    return mapRocketMerchantPaymentGuide(this.environment);
  }

  async createPayment(
    input: RocketCreatePaymentInput,
  ): Promise<RocketPaymentApiResult> {
    validateRocketCreatePaymentInput(input);
    return mapRocketManualPaymentResult(this.environment, input);
  }

  async verifyPayment(
    _input: RocketVerifyPaymentInput = {},
  ): Promise<RocketPaymentApiResult> {
    throw this.createPendingRuntimeOperationError("verifyPayment");
  }

  async queryPayment(
    _input: RocketQueryPaymentInput = {},
  ): Promise<RocketPaymentQueryApiResult> {
    throw this.createPendingRuntimeOperationError("queryPayment");
  }

  verifyNotification(
    payload: RocketNotificationPayload,
  ): RocketNotificationApiResult {
    return mapRocketNotificationVerificationResult(payload);
  }

  validateWebhook(
    payload: RocketNotificationPayload,
  ): RocketNotificationApiResult {
    return this.verifyNotification(payload);
  }

  private createPendingRuntimeOperationError(
    operation: RocketRuntimeOperationName,
  ): PaymentError {
    return new PaymentError(createRocketPendingRuntimeMessage(operation), {
      code: ROCKET_PENDING_RUNTIME_ERROR_CODE,
      context: {
        ...this.createRequestContext(operation),
        details: {
          capabilityStatus: "pending_docs",
        },
      },
    });
  }
}