import { assertNonEmptyString } from "@bd-pay-kit/core";
import type { NagadConfig } from "./types.js";

export function validateNagadConfig(config: NagadConfig): NagadConfig {
  assertNonEmptyString(config.merchantId, "merchantId is required.");
  assertNonEmptyString(config.merchantPrivateKey, "merchantPrivateKey is required.");
  assertNonEmptyString(config.pgPublicKey, "pgPublicKey is required.");
  assertNonEmptyString(config.callbackUrl, "callbackUrl is required.");
  return config;
}