export const GATEWAY_NAMES = [
  "bkash",
  "sslcommerz",
  "nagad",
  "rocket",
] as const;

export type GatewayName = (typeof GATEWAY_NAMES)[number];

export const GATEWAY_ENVIRONMENTS = ["sandbox", "production"] as const;

export type GatewayEnvironment = (typeof GATEWAY_ENVIRONMENTS)[number];

export const PAYMENT_LIFECYCLE_OPERATIONS = [
  "createPayment",
  "completePayment",
  "verifyPayment",
  "queryPayment",
  "refundPayment",
  "queryRefund",
  "verifyNotification",
] as const;

export type PaymentLifecycleOperation =
  (typeof PAYMENT_LIFECYCLE_OPERATIONS)[number];

export const AGREEMENT_LIFECYCLE_OPERATIONS = [
  "createAgreement",
  "executeAgreement",
  "queryAgreement",
  "cancelAgreement",
] as const;

export type AgreementLifecycleOperation =
  (typeof AGREEMENT_LIFECYCLE_OPERATIONS)[number];

export type NormalizedLifecycleOperation =
  | PaymentLifecycleOperation
  | AgreementLifecycleOperation;

