import { createHash } from "node:crypto";
import type { SSLCommerzNotificationPayload, SSLCommerzNotificationValue } from "./types.js";

export interface SSLCommerzHashVerificationResult {
  isVerified: boolean;
  expectedSignature?: string;
  receivedSignature?: string;
  hashString?: string;
  signedFields: readonly string[];
}

export function verifySSLCommerzNotificationHash(
  payload: SSLCommerzNotificationPayload,
  storePassword: string,
): SSLCommerzHashVerificationResult {
  const receivedSignature = toOptionalString(payload.verify_sign)?.toLowerCase();
  const verifyKey = toOptionalString(payload.verify_key);

  if (!receivedSignature || !verifyKey) {
    return {
      isVerified: false,
      receivedSignature,
      signedFields: [],
    };
  }

  const signedFields = verifyKey
    .split(",")
    .map((value) => value.trim())
    .filter((value) => value.length > 0);

  if (signedFields.length === 0) {
    return {
      isVerified: false,
      receivedSignature,
      signedFields: [],
    };
  }

  const entries = new Map<string, string>();

  for (const field of signedFields) {
    const value = toOptionalString(payload[field]);

    if (value !== undefined) {
      entries.set(field, value);
    }
  }

  entries.set("store_passwd", md5(storePassword));

  const sortedEntries = [...entries.entries()].sort(([left], [right]) =>
    left.localeCompare(right),
  );

  const hashString = sortedEntries
    .map(([key, value]) => `${key}=${value}`)
    .join("&");
  const expectedSignature = md5(hashString);

  return {
    isVerified: expectedSignature === receivedSignature,
    expectedSignature,
    receivedSignature,
    hashString,
    signedFields,
  };
}

function md5(value: string): string {
  return createHash("md5").update(value).digest("hex");
}

function toOptionalString(value: SSLCommerzNotificationValue): string | undefined {
  if (value === undefined) {
    return undefined;
  }

  return String(value);
}