import type { BkashToken, BkashTokenStore } from "./types.js";

export class InMemoryBkashTokenStore implements BkashTokenStore {
  private token: BkashToken | null = null;

  async get(): Promise<BkashToken | null> {
    return this.token;
  }

  async set(token: BkashToken): Promise<void> {
    this.token = token;
  }

  async clear(): Promise<void> {
    this.token = null;
  }
}