import { BaseGateway, PaymentError } from "@bd-pay-kit/core";
import {
  NAGAD_GATEWAY_NAME,
  NAGAD_PENDING_RUNTIME_ERROR_CODE,
  createNagadDescriptor,
  createNagadPendingRuntimeMessage,
} from "./constants.js";
import { validateNagadConfig } from "./config.js";
import {
  mapNagadCallbackVerificationResult,
  mapNagadSetupReport,
} from "./mappers.js";
import type {
  NagadCallbackPayload,
  NagadConfig,
  NagadCreatePaymentInput,
  NagadGatewayDescriptor,
  NagadNotificationApiResult,
  NagadPaymentApiResult,
  NagadPaymentQueryApiResult,
  NagadQueryPaymentInput,
  NagadRuntimeOperationName,
  NagadSetupReport,
  NagadVerifyPaymentInput,
} from "./types.js";

export class NagadClient extends BaseGateway<typeof NAGAD_GATEWAY_NAME, NagadConfig> {
  readonly descriptor: NagadGatewayDescriptor;

  constructor(config: NagadConfig) {
    validateNagadConfig(config);
    super(NAGAD_GATEWAY_NAME, config);
    this.descriptor = createNagadDescriptor(this.environment);
  }

  describeSetup(): NagadSetupReport {
    return mapNagadSetupReport(this.config);
  }

  async createPayment(
    _input: NagadCreatePaymentInput = {},
  ): Promise<NagadPaymentApiResult> {
    throw this.createPendingRuntimeOperationError("createPayment");
  }

  async verifyPayment(
    _input: NagadVerifyPaymentInput = {},
  ): Promise<NagadPaymentApiResult> {
    throw this.createPendingRuntimeOperationError("verifyPayment");
  }

  async queryPayment(
    _input: NagadQueryPaymentInput = {},
  ): Promise<NagadPaymentQueryApiResult> {
    throw this.createPendingRuntimeOperationError("queryPayment");
  }

  verifyCallback(payload: NagadCallbackPayload): NagadNotificationApiResult {
    return mapNagadCallbackVerificationResult(payload);
  }

  validateWebhook(payload: NagadCallbackPayload): NagadNotificationApiResult {
    return this.verifyCallback(payload);
  }

  verifyNotification(payload: NagadCallbackPayload): NagadNotificationApiResult {
    return this.verifyCallback(payload);
  }

  private createPendingRuntimeOperationError(
    operation: NagadRuntimeOperationName,
  ): PaymentError {
    return new PaymentError(createNagadPendingRuntimeMessage(operation), {
      code: NAGAD_PENDING_RUNTIME_ERROR_CODE,
      context: {
        ...this.createRequestContext(operation),
        details: {
          capabilityStatus: "pending_docs",
        },
      },
    });
  }
}