export function createRocketDescriptor(
  environment: "sandbox" | "production",
): GatewayDescriptor<typeof ROCKET_GATEWAY_NAME, RocketCapabilityName> {
  return {
    gateway: ROCKET_GATEWAY_NAME,
    environment,
    capabilities: ROCKET_PHASE1_CAPABILITIES,
  };
}

export function createRocketPendingRuntimeMessage(
  operation: RocketRuntimeOperationName,
): string {
  return `Rocket ${operation} is pending official backend API documentation. The current repo discovery only verifies the manual merchant-payment flow, not a public server-side API contract.`;
}