import type { GatewayEnvironment } from "@bd-pay-kit/core";

export const BKASH_GATEWAY_NAME = "bkash";

export const BKASH_DEFAULT_TIMEOUT_MS = 30_000;

export const BKASH_SANDBOX_BASE_URL = "https://tokenized.sandbox.bka.sh/v1.2.0-beta";

const BKASH_EXECUTE_PATH = "/tokenized/checkout/execute";
const BKASH_REFUND_STATUS_PATH = "/v2/tokenized-checkout/refund/payment/status";

export const BKASH_PATHS = {
  grantToken: "/tokenized/checkout/token/grant",
  refreshToken: "/tokenized/checkout/token/refresh",
  createAgreement: "/tokenized/checkout/create",
  executeAgreement: BKASH_EXECUTE_PATH,
  queryAgreement: "/tokenized/checkout/agreement/status",
  cancelAgreement: "/tokenized/checkout/agreement/cancel",
  createPayment: "/tokenized/checkout/create",
  executePayment: BKASH_EXECUTE_PATH,
  completePayment: BKASH_EXECUTE_PATH,
  queryPayment: "/tokenized/checkout/payment/status",
  searchTransaction: "/tokenized/checkout/payment/search",
  refundPayment: "/v2/tokenized-checkout/refund/payment/transaction",
  refundStatus: BKASH_REFUND_STATUS_PATH,
  queryRefund: BKASH_REFUND_STATUS_PATH,
} as const;

export const BKASH_SUCCESS_STATUS_CODE = "0000";

export function resolveBkashBaseUrl(
  environment: GatewayEnvironment,
  baseUrl?: string,
): string {
  if (baseUrl) {
    return trimTrailingSlash(baseUrl);
  }

  if (environment === "sandbox") {
    return BKASH_SANDBOX_BASE_URL;
  }

  return "";
}

export function buildBkashUrl(baseUrl: string, path: string): string {
  return `${trimTrailingSlash(baseUrl)}${path.startsWith("/") ? path : `/${path}`}`;
}

function trimTrailingSlash(value: string): string {
  return value.replace(/\/+$/, "");
}