import { ValidationError, omitUndefined } from "@bd-pay-kit/core";
import type { SSLCommerzInitPaymentInput } from "../types.js";

export function validateInitPaymentInput(input: SSLCommerzInitPaymentInput): void {
  assertRequiredString(input.totalAmount, "totalAmount");
  assertRequiredString(input.currency, "currency");
  assertRequiredString(input.transactionId, "transactionId");
  assertRequiredString(input.successUrl, "successUrl");
  assertRequiredString(input.failUrl, "failUrl");
  assertRequiredString(input.cancelUrl, "cancelUrl");
  assertRequiredString(input.shippingMethod, "shippingMethod");
  assertRequiredString(input.customer.name, "customer.name");
  assertRequiredString(input.customer.email, "customer.email");
  assertRequiredString(input.customer.addressLine1, "customer.addressLine1");
  assertRequiredString(input.customer.city, "customer.city");
  assertRequiredString(input.customer.postcode, "customer.postcode");
  assertRequiredString(input.customer.country, "customer.country");
  assertRequiredString(input.customer.phone, "customer.phone");
  assertRequiredString(input.product.name, "product.name");
  assertRequiredString(input.product.category, "product.category");
  assertRequiredString(input.product.profile, "product.profile");

  const shippingMethod = input.shippingMethod.toUpperCase();

  if (shippingMethod === "YES") {
    assertRequiredString(input.shipping?.name, "shipping.name");
    assertRequiredString(input.shipping?.addressLine1, "shipping.addressLine1");
    assertRequiredString(input.shipping?.area, "shipping.area");
    assertRequiredString(input.shipping?.city, "shipping.city");
    assertRequiredString(input.shipping?.subCity, "shipping.subCity");
    assertRequiredString(input.shipping?.postcode, "shipping.postcode");
    assertRequiredString(input.shipping?.country, "shipping.country");
  }

  if (shippingMethod === "SSLCOMMERZ_LOGISTIC") {
    assertRequiredString(toOptionalString(input.logistics?.numOfItem), "logistics.numOfItem");
    assertRequiredString(
      toOptionalString(input.logistics?.weightOfItems),
      "logistics.weightOfItems",
    );
    assertRequiredString(input.logistics?.logisticPickupId, "logistics.logisticPickupId");
    assertRequiredString(
      input.logistics?.logisticDeliveryType,
      "logistics.logisticDeliveryType",
    );
    assertRequiredString(input.shipping?.name, "shipping.name");
    assertRequiredString(input.shipping?.addressLine1, "shipping.addressLine1");
    assertRequiredString(input.shipping?.area, "shipping.area");
    assertRequiredString(input.shipping?.city, "shipping.city");
    assertRequiredString(input.shipping?.subCity, "shipping.subCity");
    assertRequiredString(input.shipping?.postcode, "shipping.postcode");
    assertRequiredString(input.shipping?.country, "shipping.country");
  }
}

export function buildInitPaymentBody(
  input: SSLCommerzInitPaymentInput,
  credentials: { storeId: string; storePassword: string },
): Record<string, string> {
  return omitUndefined({
    store_id: credentials.storeId,
    store_passwd: credentials.storePassword,
    total_amount: input.totalAmount,
    currency: input.currency,
    tran_id: input.transactionId,
    success_url: input.successUrl,
    fail_url: input.failUrl,
    cancel_url: input.cancelUrl,
    ipn_url: input.ipnUrl,
    multi_card_name: input.multiCardName,
    allowed_bin: input.allowedBin,
    cus_name: input.customer.name,
    cus_email: input.customer.email,
    cus_add1: input.customer.addressLine1,
    cus_add2: input.customer.addressLine2,
    cus_city: input.customer.city,
    cus_state: input.customer.state,
    cus_postcode: input.customer.postcode,
    cus_country: input.customer.country,
    cus_phone: input.customer.phone,
    cus_fax: input.customer.fax,
    shipping_method: input.shippingMethod,
    ship_name: input.shipping?.name,
    ship_add1: input.shipping?.addressLine1,
    ship_add2: input.shipping?.addressLine2,
    ship_area: input.shipping?.area,
    ship_city: input.shipping?.city,
    ship_sub_city: input.shipping?.subCity,
    ship_state: input.shipping?.state,
    ship_postcode: input.shipping?.postcode,
    ship_country: input.shipping?.country,
    product_name: input.product.name,
    product_category: input.product.category,
    product_profile: input.product.profile,
    product_amount: input.product.amount,
    vat: input.product.vat,
    discount_amount: input.product.discountAmount,
    convenience_fee: input.product.convenienceFee,
    cart: input.product.cart ? JSON.stringify(input.product.cart) : undefined,
    value_a: input.metadata?.valueA,
    value_b: input.metadata?.valueB,
    value_c: input.metadata?.valueC,
    value_d: input.metadata?.valueD,
    emi_option: input.emi ? (input.emi.enabled ? "1" : "0") : undefined,
    emi_max_inst_option: toOptionalString(input.emi?.maxInstallmentOption),
    emi_selected_inst: toOptionalString(input.emi?.selectedInstallment),
    emi_allow_only:
      input.emi?.allowOnly !== undefined ? (input.emi.allowOnly ? "1" : "0") : undefined,
    num_of_item: toOptionalString(input.logistics?.numOfItem),
    weight_of_items: toOptionalString(input.logistics?.weightOfItems),
    logistic_pickup_id: input.logistics?.logisticPickupId,
    logistic_delivery_type: input.logistics?.logisticDeliveryType,
  }) as Record<string, string>;
}

export function encodeSSLCommerzFormBody(body: Record<string, string>): string {
  const pairs: string[] = [];

  for (const [key, value] of Object.entries(body)) {
    pairs.push(`${encodeURIComponent(key)}=${encodeURIComponent(value)}`);
  }

  return pairs.join("&");
}

function assertRequiredString(value: string | undefined, fieldName: string): void {
  if (!value || value.trim().length === 0) {
    throw new ValidationError(`${fieldName} is required.`);
  }
}

function toOptionalString(value: string | number | undefined): string | undefined {
  if (value === undefined) {
    return undefined;
  }

  return String(value);
}