import {
  GATEWAY_ENVIRONMENTS,
  ValidationError,
  assertNonEmptyString,
} from "@bd-pay-kit/core";
import type { GatewayEnvironment } from "@bd-pay-kit/core";
import type { RocketConfig, RocketCreatePaymentInput } from "./types.js";

export function validateRocketConfig(config: RocketConfig): RocketConfig {
  if (!config || typeof config !== "object") {
    throw new ValidationError("Rocket config is required.");
  }

  if (!isGatewayEnvironment(config.environment)) {
    throw new ValidationError("environment must be one of: sandbox, production.");
  }

  return config;
}

export function validateRocketCreatePaymentInput(
  input: RocketCreatePaymentInput,
): RocketCreatePaymentInput {
  assertNonEmptyString(input.amount, "amount is required.");
  assertNonEmptyString(input.currency, "currency is required.");
  return input;
}

function isGatewayEnvironment(value: unknown): value is GatewayEnvironment {
  return typeof value === "string" &&
    (GATEWAY_ENVIRONMENTS as readonly string[]).includes(value);
}