export function createNagadDescriptor(
  environment: "sandbox" | "production",
): GatewayDescriptor<typeof NAGAD_GATEWAY_NAME, NagadCapabilityName> {
  return {
    gateway: NAGAD_GATEWAY_NAME,
    environment,
    capabilities: NAGAD_PHASE1_CAPABILITIES,
  };
}

export function createNagadPendingRuntimeMessage(
  operation: NagadRuntimeOperationName,
): string {
  return `Nagad ${operation} is pending official merchant/API documentation. The current repo discovery verifies setup prerequisites, but not a stable public runtime endpoint contract.`;
}