import { omitUndefined } from "@bd-pay-kit/core";
import {
  createAgreementQueryResult,
  createAgreementResult,
  createPaymentQueryResult,
  createPaymentResult,
  createRefundQueryResult,
  createRefundResult,
  type AgreementStatus,
  type PaymentStatus,
  type RefundStatus,
} from "@bd-pay-kit/shared";
import { BKASH_GATEWAY_NAME } from "./constants.js";
import type {
  BkashAgreementApiResult,
  BkashAgreementQueryApiResult,
  BkashAgreementResponse,
  BkashPaymentApiResult,
  BkashPaymentQueryApiResult,
  BkashPaymentResponse,
  BkashRefundApiResult,
  BkashRefundResponse,
  BkashRefundStatusApiResult,
  BkashRefundStatusResponse,
  BkashSearchTransactionResponse,
} from "./types.js";

export function mapBkashAgreementResult<TRaw extends BkashAgreementResponse>(
  raw: TRaw,
): BkashAgreementApiResult<TRaw> {
  return createAgreementResult(
    BKASH_GATEWAY_NAME,
    {
      gateway: BKASH_GATEWAY_NAME,
      status: mapBkashAgreementStatus(raw.agreementStatus),
      agreementId: raw.agreementID,
      payerReference: raw.payerReference,
      createdAt: raw.paymentCreateTime ?? raw.agreementExecuteTime,
      redirect: raw.bkashURL
        ? {
            url: raw.bkashURL,
            successCallbackUrl: raw.successCallbackURL,
            failureCallbackUrl: raw.failureCallbackURL,
            cancelCallbackUrl: raw.cancelledCallbackURL,
          }
        : undefined,
      metadata: compactMetadata({
        paymentId: raw.paymentID,
        callbackUrl: raw.callbackURL,
        customerMsisdn: raw.customerMsisdn,
        statusCode: raw.statusCode,
        statusMessage: raw.statusMessage,
      }),
    },
    raw,
  );
}

export function mapBkashAgreementQueryResult<TRaw extends BkashAgreementResponse>(
  raw: TRaw,
): BkashAgreementQueryApiResult<TRaw> {
  return createAgreementQueryResult(
    BKASH_GATEWAY_NAME,
    {
      ...mapBkashAgreementResult(raw).normalized,
      queriedAt: raw.agreementExecuteTime ?? raw.paymentCreateTime ?? raw.agreementVoidTime,
    },
    raw,
  );
}

export function mapBkashPaymentResult<TRaw extends BkashPaymentResponse>(
  raw: TRaw,
  phase: "create" | "execute" | "finalized" = "create",
): BkashPaymentApiResult<TRaw> {
  return createPaymentResult(
    BKASH_GATEWAY_NAME,
    {
      gateway: BKASH_GATEWAY_NAME,
      status: mapBkashPaymentStatus(raw.transactionStatus, phase),
      money: {
        amount: raw.amount ?? "0",
        currency: raw.currency ?? "BDT",
      },
      references: {
        providerPaymentId: raw.paymentID,
        providerTransactionId: raw.trxID,
        agreementId: raw.agreementID,
        merchantInvoiceNumber: raw.merchantInvoiceNumber,
      },
      redirect: raw.bkashURL
        ? {
            url: raw.bkashURL,
            successCallbackUrl: raw.successCallbackURL,
            failureCallbackUrl: raw.failureCallbackURL,
            cancelCallbackUrl: raw.cancelledCallbackURL,
          }
        : undefined,
      message: raw.statusMessage,
      createdAt: raw.paymentCreateTime,
      completedAt: raw.paymentExecuteTime,
      metadata: compactMetadata({
        payerReference: raw.payerReference,
        callbackUrl: raw.callbackURL,
        customerMsisdn: raw.customerMsisdn,
        intent: raw.intent,
        statusCode: raw.statusCode,
      }),
    },
    raw,
  );
}

export function mapBkashPaymentQueryResult<
  TRaw extends BkashPaymentResponse | BkashSearchTransactionResponse,
>(
  raw: TRaw,
  source: "queryPayment" | "searchTransaction",
): BkashPaymentQueryApiResult<TRaw> {
  const normalizedBase = mapBkashPaymentResult(raw, "finalized").normalized;

  return createPaymentQueryResult(
    BKASH_GATEWAY_NAME,
    {
      ...normalizedBase,
      completedAt:
        raw.paymentExecuteTime ??
        ("completedTime" in raw && typeof raw.completedTime === "string"
          ? raw.completedTime
          : normalizedBase.completedAt),
      queriedAt:
        raw.paymentExecuteTime ??
        raw.paymentCreateTime ??
        ("completedTime" in raw && typeof raw.completedTime === "string"
          ? raw.completedTime
          : undefined),
      metadata: compactMetadata({
        ...(normalizedBase.metadata ?? {}),
        source,
        transactionType:
          "transactionType" in raw && typeof raw.transactionType === "string"
            ? raw.transactionType
            : undefined,
      }),
    },
    raw,
  );
}

export function mapBkashSearchTransactionResult<TRaw extends BkashSearchTransactionResponse>(
  raw: TRaw,
): BkashPaymentQueryApiResult<TRaw> {
  return mapBkashPaymentQueryResult(raw, "searchTransaction");
}

export function mapBkashRefundResult<TRaw extends BkashRefundResponse>(
  raw: TRaw,
): BkashRefundApiResult<TRaw> {
  return createRefundResult(
    BKASH_GATEWAY_NAME,
    {
      gateway: BKASH_GATEWAY_NAME,
      status: mapBkashRefundStatus(raw.refundTransactionStatus),
      money: {
        amount: raw.refundAmount ?? "0",
        currency: raw.currency ?? "BDT",
      },
      references: {
        providerTransactionId: raw.originalTrxId,
        providerRefundId: raw.refundTrxId,
      },
      message: raw.statusMessage,
      completedAt: raw.completedTime,
      metadata: compactMetadata({
        originalTransactionAmount: raw.originalTrxAmount,
        refundReason: raw.reason,
        refundSku: raw.sku,
        statusCode: raw.statusCode,
      }),
    },
    raw,
  );
}

export function mapBkashRefundStatusResult<TRaw extends BkashRefundStatusResponse>(
  raw: TRaw,
): BkashRefundStatusApiResult<TRaw> {
  const latestRefund = raw.refundTransactions?.[raw.refundTransactions.length - 1];

  return createRefundQueryResult(
    BKASH_GATEWAY_NAME,
    {
      gateway: BKASH_GATEWAY_NAME,
      status: mapBkashRefundStatus(latestRefund?.refundTransactionStatus),
      money: {
        amount: latestRefund?.refundAmount ?? raw.originalTrxAmount ?? "0",
        currency: "BDT",
      },
      references: {
        providerTransactionId: raw.originalTrxId,
        providerRefundId: latestRefund?.refundTrxId,
      },
      message: latestRefund?.refundTransactionStatus,
      completedAt: latestRefund?.completedTime,
      queriedAt: latestRefund?.completedTime ?? raw.originalTrxCompletedTime,
      metadata: compactMetadata({
        originalTransactionAmount: raw.originalTrxAmount,
        originalTransactionCompletedTime: raw.originalTrxCompletedTime,
        refundCount: raw.refundTransactions ? String(raw.refundTransactions.length) : undefined,
      }),
    },
    raw,
  );
}

function mapBkashPaymentStatus(
  status: string | undefined,
  phase: "create" | "execute" | "finalized",
): PaymentStatus {
  switch ((status ?? "").toLowerCase()) {
    case "completed":
      return "succeeded";
    case "authorized":
      return phase === "create" ? "requires_action" : "authorized";
    case "processing":
      return "processing";
    case "failed":
      return "failed";
    case "cancelled":
    case "canceled":
      return "canceled";
    case "expired":
      return "expired";
    case "initiated":
      return phase === "create" ? "requires_action" : "pending";
    default:
      return phase === "create" ? "requires_action" : "pending";
  }
}

function mapBkashAgreementStatus(status: string | undefined): AgreementStatus {
  switch ((status ?? "").toLowerCase()) {
    case "completed":
    case "active":
      return "active";
    case "cancelled":
    case "canceled":
      return "canceled";
    case "expired":
      return "expired";
    case "failed":
      return "failed";
    case "initiated":
    default:
      return "pending";
  }
}

function mapBkashRefundStatus(status: string | undefined): RefundStatus {
  switch ((status ?? "").toLowerCase()) {
    case "completed":
      return "succeeded";
    case "processing":
      return "processing";
    case "cancelled":
    case "canceled":
      return "canceled";
    case "failed":
      return "failed";
    case "initiated":
    default:
      return "pending";
  }
}

function compactMetadata(
  metadata: Record<string, string | undefined>,
): Readonly<Record<string, string>> | undefined {
  const normalized = omitUndefined(metadata);
  const entries = Object.entries(normalized);

  if (entries.length === 0) {
    return undefined;
  }

  return Object.freeze(Object.fromEntries(entries) as Record<string, string>);
}