import type {
  AgreementStatus,
  GatewayName,
  PaymentStatus,
  RefundStatus,
} from "./enums.js";
import type {
  AgreementQueryResult,
  AgreementResult,
  NormalizedAgreement,
  NormalizedAgreementQuery,
  NormalizedPayment,
  NormalizedPaymentQuery,
  NormalizedRefund,
  NormalizedRefundQuery,
  PaymentQueryResult,
  PaymentResult,
  ProviderResult,
  RefundQueryResult,
  RefundResult,
} from "./interfaces.js";

const TERMINAL_PAYMENT_STATUSES = new Set<PaymentStatus>([
  "succeeded",
  "failed",
  "canceled",
  "expired",
  "refunded",
  "partially_refunded",
]);

const TERMINAL_REFUND_STATUSES = new Set<RefundStatus>([
  "succeeded",
  "failed",
  "canceled",
]);

const TERMINAL_AGREEMENT_STATUSES = new Set<AgreementStatus>([
  "active",
  "canceled",
  "expired",
  "failed",
]);

export function isTerminalPaymentStatus(status: PaymentStatus): boolean {
  return TERMINAL_PAYMENT_STATUSES.has(status);
}

export function isTerminalRefundStatus(status: RefundStatus): boolean {
  return TERMINAL_REFUND_STATUSES.has(status);
}

export function isTerminalAgreementStatus(status: AgreementStatus): boolean {
  return TERMINAL_AGREEMENT_STATUSES.has(status);
}

export function createProviderResult<TNormalized, TRaw>(
  gateway: GatewayName,
  normalized: TNormalized,
  raw: TRaw,
): ProviderResult<TNormalized, TRaw> {
  return {
    gateway,
    normalized,
    raw,
  };
}

export function createPaymentResult<TRaw>(
  gateway: GatewayName,
  normalized: NormalizedPayment,
  raw: TRaw,
): PaymentResult<TRaw> {
  return createProviderResult(gateway, normalized, raw);
}

export function createPaymentQueryResult<TRaw>(
  gateway: GatewayName,
  normalized: NormalizedPaymentQuery,
  raw: TRaw,
): PaymentQueryResult<TRaw> {
  return createProviderResult(gateway, normalized, raw);
}

export function createRefundResult<TRaw>(
  gateway: GatewayName,
  normalized: NormalizedRefund,
  raw: TRaw,
): RefundResult<TRaw> {
  return createProviderResult(gateway, normalized, raw);
}

export function createRefundQueryResult<TRaw>(
  gateway: GatewayName,
  normalized: NormalizedRefundQuery,
  raw: TRaw,
): RefundQueryResult<TRaw> {
  return createProviderResult(gateway, normalized, raw);
}

export function createAgreementResult<TRaw>(
  gateway: GatewayName,
  normalized: NormalizedAgreement,
  raw: TRaw,
): AgreementResult<TRaw> {
  return createProviderResult(gateway, normalized, raw);
}

export function createAgreementQueryResult<TRaw>(
  gateway: GatewayName,
  normalized: NormalizedAgreementQuery,
  raw: TRaw,
): AgreementQueryResult<TRaw> {
  return createProviderResult(gateway, normalized, raw);
}