import { ProviderApiError, ValidationError } from "@bd-pay-kit/core";
import { SSLCOMMERZ_GATEWAY_NAME } from "../constants.js";
import type {
  SSLCommerzPaymentLookupResponse,
  SSLCommerzTransactionQueryResponse,
} from "../types.js";

export function buildQueryByTransactionQuery(
  transactionId: string,
  credentials: { storeId: string; storePassword: string },
): Record<string, string | number> {
  assertRequiredString(transactionId, "transactionId");

  return {
    tran_id: transactionId,
    store_id: credentials.storeId,
    store_passwd: credentials.storePassword,
    v: 1,
    format: "json",
  };
}

export function selectTransactionRecord(
  response: SSLCommerzTransactionQueryResponse,
): SSLCommerzPaymentLookupResponse {
  const records = response.element ?? [];

  if (records.length === 0) {
    throw new ProviderApiError("SSLCommerz returned no transactions for the query.", {
      context: {
        gateway: SSLCOMMERZ_GATEWAY_NAME,
        operation: "queryByTransaction",
        details: response as unknown as Record<string, unknown>,
      },
    });
  }

  const successfulRecord = records.find((record) => {
    const status = (record.status ?? "").toUpperCase();
    return status === "VALID" || status === "VALIDATED";
  });
  const fallbackRecord = records[records.length - 1];

  if (!fallbackRecord) {
    throw new ProviderApiError("SSLCommerz returned no transactions for the query.", {
      context: {
        gateway: SSLCOMMERZ_GATEWAY_NAME,
        operation: "queryByTransaction",
        details: response as unknown as Record<string, unknown>,
      },
    });
  }

  return successfulRecord ?? fallbackRecord;
}

function assertRequiredString(value: string | undefined, fieldName: string): void {
  if (!value || value.trim().length === 0) {
    throw new ValidationError(`${fieldName} is required.`);
  }
}