import { ValidationError } from "./errors.js";

export type UnknownRecord = Record<string, unknown>;

export function isNonEmptyString(value: unknown): value is string {
  return typeof value === "string" && value.trim().length > 0;
}

export function assertNonEmptyString(
  value: unknown,
  message: string,
): asserts value is string {
  if (!isNonEmptyString(value)) {
    throw new ValidationError(message);
  }
}

export function omitUndefined<TValue extends UnknownRecord>(
  value: TValue,
): Partial<{ [TKey in keyof TValue]: Exclude<TValue[TKey], undefined> }> {
  const result: UnknownRecord = {};

  for (const [key, entry] of Object.entries(value)) {
    if (entry !== undefined) {
      result[key] = entry;
    }
  }

  return result as Partial<{ [TKey in keyof TValue]: Exclude<TValue[TKey], undefined> }>;
}

export function toReadonlyRecord(
  entries: Iterable<readonly [string, string | null | undefined]>,
): Readonly<Record<string, string>> {
  const record: Record<string, string> = {};

  for (const [key, value] of entries) {
    if (value !== undefined && value !== null) {
      record[key] = value;
    }
  }

  return Object.freeze(record);
}

export function maskSecret(value: string, visibleTailLength = 4): string {
  if (visibleTailLength <= 0) {
    return "*".repeat(value.length);
  }

  if (value.length <= visibleTailLength) {
    return "*".repeat(value.length);
  }

  const hiddenLength = Math.max(4, value.length - visibleTailLength);
  return `${"*".repeat(hiddenLength)}${value.slice(-visibleTailLength)}`;
}

export function joinUrl(baseUrl: string, path: string): string {
  const normalizedBaseUrl = baseUrl.replace(/\/+$/, "");
  const normalizedPath = path.replace(/^\/+/, "");
  return `${normalizedBaseUrl}/${normalizedPath}`;
}