import { ValidationError } from "@bd-pay-kit/core";
import { verifySSLCommerzNotificationHash } from "../hash.js";
import type { SSLCommerzNotificationPayload } from "../types.js";

export interface SSLCommerzIpnVerificationSummary {
  readonly isVerified: boolean;
  readonly message: string;
}

export function verifySSLCommerzIpnPayload(
  payload: SSLCommerzNotificationPayload,
  storePassword: string,
): SSLCommerzIpnVerificationSummary {
  if (!isRecord(payload)) {
    throw new ValidationError("verifyIpn requires an object payload.");
  }

  const verification = verifySSLCommerzNotificationHash(payload, storePassword);

  return {
    isVerified: verification.isVerified,
    message: verification.isVerified
      ? "SSLCommerz IPN hash verified. Call validatePayment with val_id before trusting settlement."
      : "SSLCommerz IPN hash verification failed.",
  };
}

function isRecord(value: unknown): value is Record<string, unknown> {
  return typeof value === "object" && value !== null && !Array.isArray(value);
}