import type { GatewayEnvironment } from "@bd-pay-kit/core";

export const SSLCOMMERZ_GATEWAY_NAME = "sslcommerz";

export const SSLCOMMERZ_DEFAULT_TIMEOUT_MS = 30_000;

export const SSLCOMMERZ_SANDBOX_BASE_URL = "https://sandbox.sslcommerz.com";

export const SSLCOMMERZ_PRODUCTION_BASE_URL = "https://securepay.sslcommerz.com";

const SSLCOMMERZ_INIT_PAYMENT_PATH = "/gwprocess/v4/api.php";
const SSLCOMMERZ_VALIDATE_PAYMENT_PATH = "/validator/api/validationserverAPI.php";
const SSLCOMMERZ_TRANSACTION_QUERY_PATH = "/validator/api/merchantTransIDvalidationAPI.php";

export const SSLCOMMERZ_PATHS = {
  initPayment: SSLCOMMERZ_INIT_PAYMENT_PATH,
  createSession: SSLCOMMERZ_INIT_PAYMENT_PATH,
  validatePayment: SSLCOMMERZ_VALIDATE_PAYMENT_PATH,
  transactionQuery: SSLCOMMERZ_TRANSACTION_QUERY_PATH,
  queryBySession: SSLCOMMERZ_TRANSACTION_QUERY_PATH,
  queryByTransaction: SSLCOMMERZ_TRANSACTION_QUERY_PATH,
  initiateRefund: SSLCOMMERZ_TRANSACTION_QUERY_PATH,
  refundQuery: SSLCOMMERZ_TRANSACTION_QUERY_PATH,
} as const;

export const SSLCOMMERZ_API_CONNECT_DONE = "DONE";

export function resolveSSLCommerzBaseUrl(
  environment: GatewayEnvironment,
  baseUrl?: string,
): string {
  if (baseUrl) {
    return trimTrailingSlash(baseUrl);
  }

  return environment === "sandbox"
    ? SSLCOMMERZ_SANDBOX_BASE_URL
    : SSLCOMMERZ_PRODUCTION_BASE_URL;
}

export function buildSSLCommerzUrl(baseUrl: string, path: string): string {
  return `${trimTrailingSlash(baseUrl)}${path.startsWith("/") ? path : `/${path}`}`;
}

function trimTrailingSlash(value: string): string {
  return value.replace(/\/+$/, "");
}