import type {
  NagadCallbackPayload,
  NagadConfig,
  NagadNotificationApiResult,
  NagadSetupReport,
} from "./types.js";
import {
  NAGAD_GATEWAY_NAME,
  NAGAD_PHASE1_CAPABILITIES,
  NAGAD_PHASE1_LIMITATIONS,
  NAGAD_PHASE1_NOTES,
  NAGAD_SETUP_REQUIREMENTS,
  NAGAD_UNVERIFIED_CALLBACK_MESSAGE,
} from "./constants.js";

export function mapNagadSetupReport(config: Readonly<NagadConfig>): NagadSetupReport {
  return {
    gateway: NAGAD_GATEWAY_NAME,
    environment: config.environment,
    callbackUrl: config.callbackUrl,
    isConfigurationComplete:
      hasText(config.merchantId) &&
      hasText(config.merchantPrivateKey) &&
      hasText(config.pgPublicKey) &&
      hasText(config.callbackUrl),
    requiresMerchantPanelCallbackRegistration: true,
    requiresMerchantPublicKeyUpload: true,
    requiresForeignServerIpWhitelisting: hasText(config.foreignServerIp),
    capabilities: NAGAD_PHASE1_CAPABILITIES,
    requirements: NAGAD_SETUP_REQUIREMENTS,
    notes: NAGAD_PHASE1_NOTES,
    limitations: NAGAD_PHASE1_LIMITATIONS,
  };
}

export function mapNagadCallbackVerificationResult<
  TRaw extends NagadCallbackPayload,
>(
  payload: TRaw,
  message = NAGAD_UNVERIFIED_CALLBACK_MESSAGE,
): NagadNotificationApiResult<TRaw> {
  return {
    gateway: NAGAD_GATEWAY_NAME,
    normalized: {
      gateway: NAGAD_GATEWAY_NAME,
      isVerified: false,
      kind: "unknown",
      message,
    },
    raw: payload,
  };
}

function hasText(value: string | undefined): boolean {
  return Boolean(value && value.trim().length > 0);
}