import { ConfigurationError, NetworkError, PaymentError } from "./errors.js";

export type HttpMethod = "GET" | "POST" | "PUT" | "PATCH" | "DELETE";

export type HttpHeaderMap = Readonly<Record<string, string>>;

export type HttpQueryValue = string | number | boolean | null | undefined;

export type HttpQueryParams = Readonly<Record<string, HttpQueryValue>>;

export type HttpParseMode = "auto" | "json" | "text";

export interface HttpRequest<TBody = unknown> {
  method: HttpMethod;
  url: string;
  headers?: HttpHeaderMap;
  query?: HttpQueryParams;
  body?: TBody;
  timeoutMs?: number;
  parseAs?: HttpParseMode;
}

export interface HttpResponse<TBody = unknown> {
  status: number;
  headers: HttpHeaderMap;
  body: TBody;
}

export interface HttpTransport {
  send<TResponse = unknown, TBody = unknown>(
    request: HttpRequest<TBody>,
  ): Promise<HttpResponse<TResponse>>;
}

export interface HttpClientOptions {
  fetch?: FetchLike;
  defaultHeaders?: HttpHeaderMap;
  defaultTimeoutMs?: number;
}

export interface FetchHeadersLike {
  get(name: string): string | null;
  forEach(callback: (value: string, key: string) => void): void;
}

export interface FetchResponseLike {
  status: number;
  headers: FetchHeadersLike;
  text(): Promise<string>;
}

export interface FetchRequestInitLike {
  method?: string;
  headers?: Record<string, string>;
  body?: string | ArrayBuffer | Uint8Array;
  signal?: unknown;
}

export interface FetchLike {
  (input: string, init?: FetchRequestInitLike): Promise<FetchResponseLike>;
}

interface AbortControllerLike {
  readonly signal: unknown;
  abort(reason?: unknown): void;
}

interface AbortControllerConstructorLike {
  new (): AbortControllerLike;
}

interface TimerGlobals {
  setTimeout?: (callback: () => void, timeoutMs: number) => unknown;
  clearTimeout?: (handle: unknown) => void;
}

export class HttpClient implements HttpTransport {
  private readonly fetchImpl: FetchLike;
  private readonly options: HttpClientOptions;

  constructor(options: HttpClientOptions = {}) {
    const fetchImpl = options.fetch ?? (globalThis as { fetch?: FetchLike }).fetch;

    if (!fetchImpl) {
      throw new ConfigurationError(
        "HttpClient requires a fetch implementation. Pass one explicitly or use Node.js 18+.",
      );
    }

    this.fetchImpl = fetchImpl;
    this.options = options;
  }

  async send<TResponse = unknown, TBody = unknown>(
    request: HttpRequest<TBody>,
  ): Promise<HttpResponse<TResponse>> {
    const url = buildUrl(request.url, request.query);
    const headers = mergeHeaders(this.options.defaultHeaders, request.headers);
    const body = prepareRequestBody(request.body, headers);
    const timeoutMs = request.timeoutMs ?? this.options.defaultTimeoutMs;
    const abortController = createAbortController();

    try {
      const response = await withTimeout(
        this.fetchImpl(url, {
          method: request.method,
          headers,
          body,
          signal: abortController?.signal,
        }),
        timeoutMs,
        abortController,
        request,
      );

      const responseHeaders = normalizeFetchHeaders(response.headers);
      const responseBody = await parseResponseBody<TResponse>(
        response,
        responseHeaders,
        request.parseAs ?? "auto",
      );

      return {
        status: response.status,
        headers: responseHeaders,
        body: responseBody,
      };
    } catch (error) {
      if (error instanceof PaymentError) {
        throw error;
      }

      throw new NetworkError("Network request failed", {
        code: "HTTP_REQUEST_FAILED",
        cause: error,
        context: {
          details: {
            method: request.method,
            url,
          },
        },
      });
    }
  }
}

export function buildUrl(url: string, query?: HttpQueryParams): string {
  if (!query) {
    return url;
  }

  const pairs: string[] = [];

  for (const [key, value] of Object.entries(query)) {
    if (value === undefined || value === null) {
      continue;
    }

    pairs.push(`${encodeURIComponent(key)}=${encodeURIComponent(String(value))}`);
  }

  if (pairs.length === 0) {
    return url;
  }

  const separator = url.includes("?") ? "&" : "?";
  return `${url}${separator}${pairs.join("&")}`;
}

function prepareRequestBody<TBody>(
  body: TBody | undefined,
  headers: Record<string, string>,
): string | ArrayBuffer | Uint8Array | undefined {
  if (body === undefined || body === null) {
    return undefined;
  }

  if (
    typeof body === "string" ||
    body instanceof Uint8Array ||
    body instanceof ArrayBuffer
  ) {
    return body;
  }

  if (!hasHeader(headers, "content-type")) {
    headers["content-type"] = "application/json";
  }

  return JSON.stringify(body);
}

async function parseResponseBody<TResponse>(
  response: FetchResponseLike,
  headers: HttpHeaderMap,
  parseAs: HttpParseMode,
): Promise<TResponse> {
  const responseText = await response.text();

  if (responseText.length === 0) {
    return undefined as TResponse;
  }

  if (parseAs === "text") {
    return responseText as TResponse;
  }

  const contentType = headers["content-type"] ?? "";
  const shouldParseJson =
    parseAs === "json" || contentType.toLowerCase().includes("application/json");

  if (!shouldParseJson) {
    return responseText as TResponse;
  }

  try {
    return JSON.parse(responseText) as TResponse;
  } catch (error) {
    throw new PaymentError("Failed to parse JSON response body", {
      code: "HTTP_RESPONSE_PARSE_ERROR",
      cause: error,
      context: {
        statusCode: response.status,
        details: {
          contentType,
        },
      },
    });
  }
}

function normalizeRequestHeaders(headers?: HttpHeaderMap): Record<string, string> {
  const normalized: Record<string, string> = {};

  if (!headers) {
    return normalized;
  }

  for (const [key, value] of Object.entries(headers)) {
    normalized[key.toLowerCase()] = value;
  }

  return normalized;
}

function normalizeFetchHeaders(headers: FetchHeadersLike): Record<string, string> {
  const normalized: Record<string, string> = {};

  headers.forEach((value, key) => {
    normalized[key.toLowerCase()] = value;
  });

  return normalized;
}

function mergeHeaders(
  baseHeaders?: HttpHeaderMap,
  requestHeaders?: HttpHeaderMap,
): Record<string, string> {
  return {
    ...normalizeRequestHeaders(baseHeaders),
    ...normalizeRequestHeaders(requestHeaders),
  };
}

function hasHeader(headers: Record<string, string>, name: string): boolean {
  return Object.prototype.hasOwnProperty.call(headers, name.toLowerCase());
}

function createAbortController(): AbortControllerLike | null {
  const AbortControllerImpl = (globalThis as {
    AbortController?: AbortControllerConstructorLike;
  }).AbortController;

  return AbortControllerImpl ? new AbortControllerImpl() : null;
}

function withTimeout<T>(
  promise: Promise<T>,
  timeoutMs: number | undefined,
  abortController: AbortControllerLike | null,
  request: HttpRequest<unknown>,
): Promise<T> {
  if (!timeoutMs || timeoutMs <= 0) {
    return promise;
  }

  const timers = globalThis as TimerGlobals;

  if (!timers.setTimeout || !timers.clearTimeout) {
    return promise;
  }

  return new Promise<T>((resolve, reject) => {
    const timeoutHandle = timers.setTimeout?.(() => {
      abortController?.abort("timeout");
      reject(
        new NetworkError(`Request timed out after ${timeoutMs}ms`, {
          code: "HTTP_TIMEOUT",
          context: {
            details: {
              method: request.method,
              url: request.url,
            },
          },
        }),
      );
    }, timeoutMs);

    promise.then(
      (value) => {
        if (timeoutHandle !== undefined) {
          timers.clearTimeout?.(timeoutHandle);
        }
        resolve(value);
      },
      (error) => {
        if (timeoutHandle !== undefined) {
          timers.clearTimeout?.(timeoutHandle);
        }
        reject(error);
      },
    );
  });
}