export const GATEWAY_ENVIRONMENTS = ["sandbox", "production"] as const;

export type GatewayEnvironment = (typeof GATEWAY_ENVIRONMENTS)[number];

export type GatewayCapabilityStatus =
  | "documented"
  | "partial"
  | "pending_docs"
  | "unsupported";

export interface BaseGatewayConfig {
  environment: GatewayEnvironment;
  timeoutMs?: number;
  debug?: boolean;
}

export interface GatewayRequestContext<
  TGateway extends string = string,
  TOperation extends string = string,
> {
  gateway: TGateway;
  operation: TOperation;
  environment: GatewayEnvironment;
  requestId?: string;
  merchantInvoiceNumber?: string;
}

export type GatewayRequestContextOverrides<
  TGateway extends string = string,
  TOperation extends string = string,
> = Partial<
  Omit<GatewayRequestContext<TGateway, TOperation>, "gateway" | "operation" | "environment">
>;

export interface GatewayCapability<TName extends string = string> {
  name: TName;
  status: GatewayCapabilityStatus;
  notes?: string;
}

export interface GatewayDescriptor<
  TGateway extends string = string,
  TCapability extends string = string,
> {
  gateway: TGateway;
  environment: GatewayEnvironment;
  capabilities?: readonly GatewayCapability<TCapability>[];
}

export interface BaseGatewayClient<TGateway extends string = string> {
  readonly gateway: TGateway;
  readonly environment: GatewayEnvironment;
}

export abstract class BaseGateway<
  TGateway extends string,
  TConfig extends BaseGatewayConfig = BaseGatewayConfig,
> implements BaseGatewayClient<TGateway>
{
  readonly gateway: TGateway;
  readonly environment: GatewayEnvironment;

  protected readonly config: Readonly<TConfig>;

  protected constructor(gateway: TGateway, config: TConfig) {
    this.gateway = gateway;
    this.environment = config.environment;
    this.config = Object.freeze({ ...config });
  }

  protected get timeoutMs(): number | undefined {
    return this.config.timeoutMs;
  }

  protected get isDebugEnabled(): boolean {
    return this.config.debug ?? false;
  }

  protected createRequestContext<TOperation extends string>(
    operation: TOperation,
    overrides: GatewayRequestContextOverrides<TGateway, TOperation> = {},
  ): GatewayRequestContext<TGateway, TOperation> {
    return {
      gateway: this.gateway,
      operation,
      environment: this.environment,
      ...overrides,
    };
  }

  describe<TCapability extends string = string>(
    capabilities?: readonly GatewayCapability<TCapability>[],
  ): GatewayDescriptor<TGateway, TCapability> {
    return {
      gateway: this.gateway,
      environment: this.environment,
      capabilities,
    };
  }
}