import {
  BaseGateway,
  HttpClient,
  ProviderApiError,
  ValidationError,
  type HttpResponse,
  type HttpTransport,
} from "@bd-pay-kit/core";
import {
  SSLCOMMERZ_API_CONNECT_DONE,
  SSLCOMMERZ_GATEWAY_NAME,
  SSLCOMMERZ_PATHS,
  buildSSLCommerzUrl,
} from "./constants.js";
import { resolveSSLCommerzConfig } from "./config.js";
import {
  mapSSLCommerzInitPaymentResult,
  mapSSLCommerzNotificationResult,
  mapSSLCommerzQueryBySessionResult,
  mapSSLCommerzQueryByTransactionResult,
  mapSSLCommerzInitiateRefundResult,
  mapSSLCommerzRefundQueryResult,
  mapSSLCommerzValidatePaymentResult,
} from "./mappers/index.js";
import { buildInitPaymentBody, encodeSSLCommerzFormBody, validateInitPaymentInput } from "./payment/initPayment.js";
import { buildQueryBySessionQuery } from "./payment/queryBySession.js";
import { buildQueryByTransactionQuery, selectTransactionRecord } from "./payment/queryByTransaction.js";
import { buildValidatePaymentQuery } from "./payment/validatePayment.js";
import { buildInitiateRefundQuery } from "./refund/initiateRefund.js";
import { buildRefundQuery } from "./refund/refundQuery.js";
import type {
  SSLCommerzBaseResponse,
  SSLCommerzConfig,
  SSLCommerzCreatePaymentInput,
  SSLCommerzCreatePaymentResult,
  SSLCommerzInitPaymentInput,
  SSLCommerzInitPaymentResult,
  SSLCommerzInitiateRefundInput,
  SSLCommerzInitiateRefundResult,
  SSLCommerzNotificationApiResult,
  SSLCommerzNotificationPayload,
  SSLCommerzPaymentApiResult,
  SSLCommerzPaymentLookupResponse,
  SSLCommerzPaymentQueryResult,
  SSLCommerzQueryBySessionInput,
  SSLCommerzQueryByTransactionInput,
  SSLCommerzQueryPaymentInput,
  SSLCommerzQueryRefundInput,
  SSLCommerzRefundPaymentInput,
  SSLCommerzRefundQueryInput,
  SSLCommerzRefundQueryResponse,
  SSLCommerzRefundQueryResult,
  SSLCommerzRefundResponse,
  SSLCommerzSessionResponse,
  SSLCommerzTransactionQueryResponse,
  SSLCommerzValidatePaymentInput,
  SSLCommerzValidatePaymentResult,
  SSLCommerzVerifyPaymentInput,
} from "./types.js";
import { verifySSLCommerzIpnPayload } from "./webhook/verifyIpn.js";

export class SSLCommerzClient extends BaseGateway<
  typeof SSLCOMMERZ_GATEWAY_NAME,
  SSLCommerzConfig
> {
  private readonly baseUrl: string;
  private readonly transport: HttpTransport;
  private readonly requestTimeoutMs: number;
  private readonly credentials: {
    storeId: string;
    storePassword: string;
  };

  constructor(config: SSLCommerzConfig) {
    super(SSLCOMMERZ_GATEWAY_NAME, config);

    const resolved = resolveSSLCommerzConfig(config);

    this.baseUrl = resolved.baseUrl;
    this.requestTimeoutMs = resolved.timeoutMs;
    this.credentials = {
      storeId: resolved.storeId,
      storePassword: resolved.storePassword,
    };
    this.transport =
      config.transport ??
      new HttpClient({
        defaultHeaders: {
          accept: "application/json",
        },
        defaultTimeoutMs: this.requestTimeoutMs,
      });
  }

  async initPayment(
    input: SSLCommerzInitPaymentInput,
  ): Promise<SSLCommerzInitPaymentResult> {
    validateInitPaymentInput(input);

    const response = await this.transport.send<SSLCommerzSessionResponse, string>({
      method: "POST",
      url: this.buildUrl(SSLCOMMERZ_PATHS.initPayment),
      headers: {
        "content-type": "application/x-www-form-urlencoded",
      },
      body: encodeSSLCommerzFormBody(
        buildInitPaymentBody(input, this.credentials),
      ),
      parseAs: "json",
      timeoutMs: this.requestTimeoutMs,
    });

    const raw = this.assertSessionSuccess(response, "initPayment");
    return mapSSLCommerzInitPaymentResult(raw, input);
  }

  async createPayment(
    input: SSLCommerzCreatePaymentInput,
  ): Promise<SSLCommerzCreatePaymentResult> {
    return this.initPayment(input);
  }

  async validatePayment(
    input: SSLCommerzValidatePaymentInput,
  ): Promise<SSLCommerzValidatePaymentResult<SSLCommerzPaymentLookupResponse>> {
    const response = await this.transport.send<SSLCommerzPaymentLookupResponse>({
      method: "GET",
      url: this.buildUrl(SSLCOMMERZ_PATHS.validatePayment),
      query: buildValidatePaymentQuery(input.validationId, this.credentials),
      parseAs: "json",
      timeoutMs: this.requestTimeoutMs,
    });

    const raw = this.assertVerificationSuccess(response, "validatePayment");
    return mapSSLCommerzValidatePaymentResult(raw);
  }

  async verifyPayment(
    input: SSLCommerzVerifyPaymentInput,
  ): Promise<SSLCommerzPaymentApiResult<SSLCommerzPaymentLookupResponse>> {
    return this.validatePayment(input);
  }

  async queryBySession(
    input: SSLCommerzQueryBySessionInput,
  ): Promise<SSLCommerzPaymentQueryResult<SSLCommerzPaymentLookupResponse>> {
    const response = await this.transport.send<SSLCommerzPaymentLookupResponse>({
      method: "GET",
      url: this.buildUrl(SSLCOMMERZ_PATHS.queryBySession),
      query: buildQueryBySessionQuery(input.sessionKey, this.credentials),
      parseAs: "json",
      timeoutMs: this.requestTimeoutMs,
    });

    const raw = this.assertLookupSuccess<SSLCommerzPaymentLookupResponse>(
      response,
      "queryBySession",
    );
    return mapSSLCommerzQueryBySessionResult(raw);
  }

  async queryByTransaction(
    input: SSLCommerzQueryByTransactionInput,
  ): Promise<SSLCommerzPaymentQueryResult<SSLCommerzTransactionQueryResponse>> {
    const response = await this.transport.send<SSLCommerzTransactionQueryResponse>({
      method: "GET",
      url: this.buildUrl(SSLCOMMERZ_PATHS.queryByTransaction),
      query: buildQueryByTransactionQuery(input.transactionId, this.credentials),
      parseAs: "json",
      timeoutMs: this.requestTimeoutMs,
    });

    const raw = this.assertTransactionQuerySuccess(response, "queryByTransaction");
    const selected = selectTransactionRecord(raw);

    return mapSSLCommerzQueryByTransactionResult(raw, selected);
  }

  async queryPayment(
    input: SSLCommerzQueryPaymentInput,
  ): Promise<SSLCommerzPaymentQueryResult> {
    if ((input.sessionKey ? 1 : 0) + (input.transactionId ? 1 : 0) !== 1) {
      throw new ValidationError(
        "queryPayment requires exactly one of sessionKey or transactionId.",
      );
    }

    if (input.sessionKey) {
      return this.queryBySession({ sessionKey: input.sessionKey });
    }

    const transactionId = "transactionId" in input ? input.transactionId : undefined;

    if (!transactionId) {
      throw new ValidationError("queryPayment requires a transactionId when sessionKey is not provided.");
    }

    return this.queryByTransaction({ transactionId });
  }

  async initiateRefund(
    input: SSLCommerzInitiateRefundInput,
  ): Promise<SSLCommerzInitiateRefundResult<SSLCommerzRefundResponse>> {
    const response = await this.transport.send<SSLCommerzRefundResponse>({
      method: "GET",
      url: this.buildUrl(SSLCOMMERZ_PATHS.initiateRefund),
      query: buildInitiateRefundQuery(input, this.credentials),
      parseAs: "json",
      timeoutMs: this.requestTimeoutMs,
    });

    const raw = this.assertRefundInitiationSuccess(response, "initiateRefund");
    return mapSSLCommerzInitiateRefundResult(raw);
  }

  async refundPayment(
    input: SSLCommerzRefundPaymentInput,
  ): Promise<SSLCommerzInitiateRefundResult<SSLCommerzRefundResponse>> {
    return this.initiateRefund(input);
  }

  async refundQuery(
    input: SSLCommerzRefundQueryInput,
  ): Promise<SSLCommerzRefundQueryResult<SSLCommerzRefundQueryResponse>> {
    const response = await this.transport.send<SSLCommerzRefundQueryResponse>({
      method: "GET",
      url: this.buildUrl(SSLCOMMERZ_PATHS.refundQuery),
      query: buildRefundQuery(input.refundReferenceId, this.credentials),
      parseAs: "json",
      timeoutMs: this.requestTimeoutMs,
    });

    const raw = this.assertRefundLookupSuccess(response, "refundQuery");
    return mapSSLCommerzRefundQueryResult(raw);
  }

  async queryRefund(
    input: SSLCommerzQueryRefundInput,
  ): Promise<SSLCommerzRefundQueryResult<SSLCommerzRefundQueryResponse>> {
    return this.refundQuery(input);
  }

  verifyIpn(
    payload: SSLCommerzNotificationPayload,
  ): SSLCommerzNotificationApiResult {
    const verification = verifySSLCommerzIpnPayload(
      payload,
      this.credentials.storePassword,
    );

    return mapSSLCommerzNotificationResult(
      payload,
      verification.isVerified,
      verification.message,
    );
  }

  verifyNotification(
    payload: SSLCommerzNotificationPayload,
  ): SSLCommerzNotificationApiResult {
    return this.verifyIpn(payload);
  }

  private assertSessionSuccess(
    response: HttpResponse<unknown>,
    operation: string,
  ): SSLCommerzSessionResponse {
    const raw = this.assertObjectResponse<SSLCommerzSessionResponse>(response, operation);

    if (raw.status !== "SUCCESS" || !raw.sessionkey || !raw.GatewayPageURL) {
      throw new ProviderApiError(raw.failedreason ?? `SSLCommerz ${operation} failed`, {
        context: {
          ...this.createRequestContext(operation),
          statusCode: response.status,
          details: raw as Record<string, unknown>,
        },
      });
    }

    return raw;
  }

  private assertVerificationSuccess(
    response: HttpResponse<unknown>,
    operation: string,
  ): SSLCommerzPaymentLookupResponse {
    const raw = this.assertObjectResponse<SSLCommerzPaymentLookupResponse>(response, operation);
    const normalizedStatus = (raw.status ?? "").toUpperCase();

    if (normalizedStatus !== "VALID" && normalizedStatus !== "VALIDATED") {
      throw new ProviderApiError(raw.status ?? `SSLCommerz ${operation} failed`, {
        context: {
          ...this.createRequestContext(operation),
          statusCode: response.status,
          details: raw as Record<string, unknown>,
        },
      });
    }

    return raw;
  }

  private assertLookupSuccess<TResponse extends SSLCommerzBaseResponse>(
    response: HttpResponse<unknown>,
    operation: string,
  ): TResponse {
    const raw = this.assertObjectResponse<TResponse>(response, operation);

    if (raw.APIConnect && raw.APIConnect !== SSLCOMMERZ_API_CONNECT_DONE) {
      throw new ProviderApiError(
        raw.errorReason ?? raw.failedreason ?? `SSLCommerz ${operation} failed`,
        {
          context: {
            ...this.createRequestContext(operation),
            statusCode: response.status,
            providerCode: raw.APIConnect,
            details: raw as Record<string, unknown>,
          },
        },
      );
    }

    return raw;
  }

  private assertTransactionQuerySuccess(
    response: HttpResponse<unknown>,
    operation: string,
  ): SSLCommerzTransactionQueryResponse {
    const raw = this.assertLookupSuccess<SSLCommerzTransactionQueryResponse>(
      response,
      operation,
    );

    if (!Array.isArray(raw.element) || raw.element.length === 0) {
      throw new ProviderApiError("SSLCommerz returned no transactions for the query.", {
        context: {
          ...this.createRequestContext(operation),
          statusCode: response.status,
          details: raw as Record<string, unknown>,
        },
      });
    }

    return raw;
  }

  private assertRefundInitiationSuccess(
    response: HttpResponse<unknown>,
    operation: string,
  ): SSLCommerzRefundResponse {
    const raw = this.assertLookupSuccess<SSLCommerzRefundResponse>(response, operation);
    const status = (raw.status ?? "").toLowerCase();

    if (!status || status === "failed") {
      throw new ProviderApiError(raw.errorReason ?? `SSLCommerz ${operation} failed`, {
        context: {
          ...this.createRequestContext(operation),
          statusCode: response.status,
          details: raw as Record<string, unknown>,
        },
      });
    }

    return raw;
  }

  private assertRefundLookupSuccess(
    response: HttpResponse<unknown>,
    operation: string,
  ): SSLCommerzRefundQueryResponse {
    const raw = this.assertLookupSuccess<SSLCommerzRefundQueryResponse>(response, operation);

    if (!raw.status) {
      throw new ProviderApiError(`SSLCommerz ${operation} returned no refund status.`, {
        context: {
          ...this.createRequestContext(operation),
          statusCode: response.status,
          details: raw as Record<string, unknown>,
        },
      });
    }

    return raw;
  }

  private assertObjectResponse<TResponse>(
    response: HttpResponse<unknown>,
    operation: string,
  ): TResponse {
    if (response.status >= 400) {
      throw new ProviderApiError(`SSLCommerz ${operation} failed`, {
        context: {
          ...this.createRequestContext(operation),
          statusCode: response.status,
          details: isRecord(response.body) ? response.body : undefined,
        },
      });
    }

    if (!isRecord(response.body)) {
      throw new ProviderApiError("SSLCommerz returned a non-object response payload", {
        context: {
          ...this.createRequestContext(operation),
          statusCode: response.status,
        },
      });
    }

    return response.body as TResponse;
  }

  private buildUrl(path: string): string {
    return buildSSLCommerzUrl(this.baseUrl, path);
  }
}

function isRecord(value: unknown): value is Record<string, unknown> {
  return typeof value === "object" && value !== null && !Array.isArray(value);
}