import {
  AuthenticationError,
  BaseGateway,
  ConfigurationError,
  HttpClient,
  ProviderApiError,
  ValidationError,
  assertNonEmptyString,
  omitUndefined,
  type HttpResponse,
  type HttpTransport,
} from "@bd-pay-kit/core";
import {
  BKASH_DEFAULT_TIMEOUT_MS,
  BKASH_GATEWAY_NAME,
  BKASH_PATHS,
  BKASH_SUCCESS_STATUS_CODE,
  buildBkashUrl,
  resolveBkashBaseUrl,
} from "./constants.js";
import {
  mapBkashAgreementQueryResult,
  mapBkashAgreementResult,
  mapBkashPaymentQueryResult,
  mapBkashPaymentResult,
  mapBkashRefundResult,
  mapBkashRefundStatusResult,
  mapBkashSearchTransactionResult,
} from "./mappers.js";
import { InMemoryBkashTokenStore } from "./token-store.js";
import type {
  BkashAgreementApiResult,
  BkashAgreementQueryApiResult,
  BkashAgreementResponse,
  BkashApiErrorPayload,
  BkashBaseResponse,
  BkashCancelAgreementInput,
  BkashCompletePaymentInput,
  BkashConfig,
  BkashCreateAgreementInput,
  BkashCreatePaymentInput,
  BkashCreatePaymentWithAgreementInput,
  BkashExecuteAgreementInput,
  BkashExecutePaymentInput,
  BkashExecutePaymentWithAgreementInput,
  BkashPaymentApiResult,
  BkashPaymentQueryApiResult,
  BkashPaymentResponse,
  BkashQueryAgreementInput,
  BkashQueryPaymentInput,
  BkashQueryRefundInput,
  BkashRefundApiResult,
  BkashRefundPaymentInput,
  BkashRefundResponse,
  BkashRefundStatusApiResult,
  BkashRefundStatusInput,
  BkashRefundStatusResponse,
  BkashSearchTransactionInput,
  BkashSearchTransactionResponse,
  BkashToken,
  BkashTokenApiResponse,
  BkashTokenStore,
} from "./types.js";

const TOKEN_EXPIRY_BUFFER_MS = 30_000;

export class BkashClient extends BaseGateway<typeof BKASH_GATEWAY_NAME, BkashConfig> {
  private readonly baseUrl: string;
  private readonly callbackBaseUrl?: string;
  private readonly transport: HttpTransport;
  private readonly tokenStore: BkashTokenStore;
  private readonly requestTimeoutMs: number;
  private readonly credentials: {
    username: string;
    password: string;
    appKey: string;
    appSecret: string;
  };

  constructor(config: BkashConfig) {
    super(BKASH_GATEWAY_NAME, config);

    this.baseUrl = resolveBkashBaseUrl(config.environment, config.baseUrl);

    if (!this.baseUrl) {
      throw new ConfigurationError(
        "bKash production baseUrl must be provided explicitly because onboarding supplies the production endpoint.",
      );
    }

    this.callbackBaseUrl = config.callbackBaseUrl;
    this.requestTimeoutMs = config.timeoutMs ?? BKASH_DEFAULT_TIMEOUT_MS;
    this.transport =
      config.transport ??
      new HttpClient({
        defaultHeaders: {
          accept: "application/json",
        },
        defaultTimeoutMs: this.requestTimeoutMs,
      });
    this.tokenStore = config.tokenStore ?? new InMemoryBkashTokenStore();
    this.credentials = {
      username: config.username,
      password: config.password,
      appKey: config.appKey,
      appSecret: config.appSecret,
    };
  }

  async grantToken(): Promise<BkashToken> {
    const response = await this.transport.send<BkashTokenApiResponse, Record<string, string>>({
      method: "POST",
      url: this.buildUrl(BKASH_PATHS.grantToken),
      headers: {
        "content-type": "application/json",
        username: this.credentials.username,
        password: this.credentials.password,
      },
      body: {
        app_key: this.credentials.appKey,
        app_secret: this.credentials.appSecret,
      },
      parseAs: "json",
      timeoutMs: this.requestTimeoutMs,
    });

    const payload = this.assertBkashSuccess<BkashTokenApiResponse>(response, "grantToken", "auth");
    const token = normalizeToken(payload);
    await this.tokenStore.set(token);
    return token;
  }

  async refreshToken(refreshToken?: string): Promise<BkashToken> {
    const cachedToken = refreshToken ? null : await this.tokenStore.get();
    const refreshTokenValue = refreshToken ?? cachedToken?.refreshToken;

    if (!refreshTokenValue) {
      throw new ValidationError(
        "refreshToken requires either an explicit refresh token or a previously cached token.",
      );
    }

    const response = await this.transport.send<BkashTokenApiResponse, Record<string, string>>({
      method: "POST",
      url: this.buildUrl(BKASH_PATHS.refreshToken),
      headers: {
        "content-type": "application/json",
        username: this.credentials.username,
        password: this.credentials.password,
      },
      body: {
        app_key: this.credentials.appKey,
        app_secret: this.credentials.appSecret,
        refresh_token: refreshTokenValue,
      },
      parseAs: "json",
      timeoutMs: this.requestTimeoutMs,
    });

    const payload = this.assertBkashSuccess<BkashTokenApiResponse>(response, "refreshToken", "auth");
    const token = normalizeToken(payload);
    await this.tokenStore.set(token);
    return token;
  }

  async createAgreement(
    input: BkashCreateAgreementInput,
  ): Promise<BkashAgreementApiResult> {
    requireString(input.payerReference, "payerReference");

    const raw = await this.sendAuthorized<BkashAgreementResponse>(
      "createAgreement",
      BKASH_PATHS.createAgreement,
      omitUndefined({
        mode: "0000",
        payerReference: input.payerReference,
        callbackURL: this.resolveCallbackUrl(input.callbackUrl),
        amount: input.amount,
        currency: input.amount ? input.currency ?? "BDT" : undefined,
        intent: input.amount ? input.intent ?? "sale" : undefined,
        merchantInvoiceNumber: input.merchantInvoiceNumber,
      }),
    );

    return mapBkashAgreementResult(raw);
  }

  async executeAgreement(
    input: BkashExecuteAgreementInput,
  ): Promise<BkashAgreementApiResult> {
    requireString(input.paymentId, "paymentId");

    const raw = await this.sendAuthorized<BkashAgreementResponse>(
      "executeAgreement",
      BKASH_PATHS.executeAgreement,
      {
        paymentID: input.paymentId,
      },
    );

    return mapBkashAgreementResult(raw);
  }

  async cancelAgreement(
    input: BkashCancelAgreementInput,
  ): Promise<BkashAgreementApiResult> {
    requireString(input.agreementId, "agreementId");

    const raw = await this.sendAuthorized<BkashAgreementResponse>(
      "cancelAgreement",
      BKASH_PATHS.cancelAgreement,
      {
        agreementID: input.agreementId,
      },
    );

    return mapBkashAgreementResult(raw);
  }

  async queryAgreement(
    input: BkashQueryAgreementInput,
  ): Promise<BkashAgreementQueryApiResult> {
    requireString(input.agreementId, "agreementId");

    const raw = await this.sendAuthorized<BkashAgreementResponse>(
      "queryAgreement",
      BKASH_PATHS.queryAgreement,
      {
        agreementID: input.agreementId,
      },
    );

    return mapBkashAgreementQueryResult(raw);
  }

  async createPayment(
    input: BkashCreatePaymentInput,
  ): Promise<BkashPaymentApiResult> {
    return this.createPaymentWithAgreement(input);
  }

  async createPaymentWithAgreement(
    input: BkashCreatePaymentWithAgreementInput,
  ): Promise<BkashPaymentApiResult> {
    requireString(input.agreementId, "agreementId");
    requireString(input.payerReference, "payerReference");
    requireString(input.amount, "amount");
    requireString(input.merchantInvoiceNumber, "merchantInvoiceNumber");

    const raw = await this.sendAuthorized<BkashPaymentResponse>(
      "createPayment",
      BKASH_PATHS.createPayment,
      omitUndefined({
        agreementID: input.agreementId,
        mode: "0001",
        payerReference: input.payerReference,
        callbackURL: this.resolveCallbackUrl(input.callbackUrl),
        merchantAssociationInfo: input.merchantAssociationInfo,
        amount: input.amount,
        currency: input.currency ?? "BDT",
        intent: input.intent ?? "sale",
        merchantInvoiceNumber: input.merchantInvoiceNumber,
      }),
    );

    return mapBkashPaymentResult(raw, "create");
  }

  async executePayment(
    input: BkashExecutePaymentInput,
  ): Promise<BkashPaymentApiResult> {
    requireString(input.paymentId, "paymentId");

    const raw = await this.sendAuthorized<BkashPaymentResponse>(
      "executePayment",
      BKASH_PATHS.executePayment,
      {
        paymentID: input.paymentId,
      },
    );

    return mapBkashPaymentResult(raw, "execute");
  }

  async executePaymentWithAgreement(
    input: BkashExecutePaymentWithAgreementInput,
  ): Promise<BkashPaymentApiResult> {
    return this.executePayment(input);
  }

  async completePayment(
    input: BkashCompletePaymentInput,
  ): Promise<BkashPaymentApiResult> {
    return this.executePayment(input);
  }

  async queryPayment(
    input: BkashQueryPaymentInput,
  ): Promise<BkashPaymentQueryApiResult> {
    requireString(input.paymentId, "paymentId");

    const raw = await this.sendAuthorized<BkashPaymentResponse>(
      "queryPayment",
      BKASH_PATHS.queryPayment,
      {
        paymentID: input.paymentId,
      },
    );

    return mapBkashPaymentQueryResult(raw, "queryPayment");
  }

  async searchTransaction(
    input: BkashSearchTransactionInput,
  ): Promise<BkashPaymentQueryApiResult<BkashSearchTransactionResponse>> {
    requireString(input.trxId, "trxId");

    const raw = await this.sendAuthorized<BkashSearchTransactionResponse>(
      "searchTransaction",
      BKASH_PATHS.searchTransaction,
      {
        trxID: input.trxId,
      },
    );

    return mapBkashSearchTransactionResult(raw);
  }

  async refundPayment(
    input: BkashRefundPaymentInput,
  ): Promise<BkashRefundApiResult<BkashRefundResponse>> {
    requireString(input.paymentId, "paymentId");
    requireString(input.trxId, "trxId");
    requireString(input.refundAmount, "refundAmount");
    requireString(input.reason, "reason");

    const raw = await this.sendAuthorized<BkashRefundResponse>(
      "refundPayment",
      BKASH_PATHS.refundPayment,
      omitUndefined({
        paymentId: input.paymentId,
        trxId: input.trxId,
        refundAmount: input.refundAmount,
        sku: input.sku,
        reason: input.reason,
      }),
    );

    return mapBkashRefundResult(raw);
  }

  async refundStatus(
    input: BkashRefundStatusInput,
  ): Promise<BkashRefundStatusApiResult<BkashRefundStatusResponse>> {
    requireString(input.paymentId, "paymentId");
    requireString(input.trxId, "trxId");

    const raw = await this.sendAuthorized<BkashRefundStatusResponse>(
      "refundStatus",
      BKASH_PATHS.refundStatus,
      {
        paymentId: input.paymentId,
        trxId: input.trxId,
      },
    );

    return mapBkashRefundStatusResult(raw);
  }

  async queryRefund(
    input: BkashQueryRefundInput,
  ): Promise<BkashRefundStatusApiResult<BkashRefundStatusResponse>> {
    return this.refundStatus(input);
  }

  private async sendAuthorized<TResponse extends BkashBaseResponse>(
    operation: string,
    path: string,
    body: Record<string, string | undefined>,
  ): Promise<TResponse> {
    const token = await this.getActiveToken();
    const response = await this.transport.send<TResponse, Record<string, string>>({
      method: "POST",
      url: this.buildUrl(path),
      headers: {
        "content-type": "application/json",
        authorization: token.idToken,
        "x-app-key": this.credentials.appKey,
      },
      body: compactRequestBody(body),
      parseAs: "json",
      timeoutMs: this.requestTimeoutMs,
    });

    return this.assertBkashSuccess<TResponse>(response, operation, "api");
  }

  private async getActiveToken(): Promise<BkashToken> {
    const cachedToken = await this.tokenStore.get();

    if (cachedToken && cachedToken.expiresAt > Date.now() + TOKEN_EXPIRY_BUFFER_MS) {
      return cachedToken;
    }

    if (cachedToken?.refreshToken) {
      try {
        return await this.refreshToken(cachedToken.refreshToken);
      } catch {
        await this.tokenStore.clear();
      }
    }

    return this.grantToken();
  }

  private assertBkashSuccess<TResponse extends BkashBaseResponse>(
    response: HttpResponse<unknown>,
    operation: string,
    errorMode: "auth" | "api",
  ): TResponse {
    if (!isRecord(response.body)) {
      throw new ProviderApiError("bKash returned a non-object response payload", {
        context: {
          ...this.createRequestContext(operation),
          statusCode: response.status,
        },
      });
    }

    const payload = response.body as TResponse;
    const errorInfo = extractBkashError(payload);
    const hasFailureStatusCode =
      payload.statusCode !== undefined && payload.statusCode !== BKASH_SUCCESS_STATUS_CODE;

    if (response.status >= 400 || hasFailureStatusCode || errorInfo) {
      const ErrorType = errorMode === "auth" ? AuthenticationError : ProviderApiError;
      throw new ErrorType(errorInfo?.message ?? `bKash ${operation} failed`, {
        context: {
          ...this.createRequestContext(operation),
          statusCode: response.status,
          providerCode: errorInfo?.code ?? payload.statusCode,
          details: payload as Record<string, unknown>,
        },
      });
    }

    return payload;
  }

  private resolveCallbackUrl(callbackUrl?: string): string {
    const resolved = callbackUrl ?? this.callbackBaseUrl;

    if (!resolved) {
      throw new ConfigurationError(
        "A callback URL is required. Pass callbackUrl per request or set callbackBaseUrl in the client config.",
      );
    }

    return resolved;
  }

  private buildUrl(path: string): string {
    return buildBkashUrl(this.baseUrl, path);
  }
}

function extractBkashError(
  payload: BkashBaseResponse & BkashApiErrorPayload,
): { code?: string; message: string } | null {
  if (payload.errorCode || payload.errorMessage) {
    return {
      code: payload.errorCode,
      message: payload.errorMessage ?? "bKash reported an error.",
    };
  }

  if (payload.externalCode || payload.errorMessageEn) {
    return {
      code: payload.externalCode ?? payload.internalCode,
      message: payload.errorMessageEn ?? payload.errorMessageBn ?? "bKash reported an error.",
    };
  }

  if (payload.statusCode && payload.statusCode !== BKASH_SUCCESS_STATUS_CODE) {
    return {
      code: payload.statusCode,
      message: payload.statusMessage ?? "bKash request failed.",
    };
  }

  return null;
}

function normalizeToken(response: BkashTokenApiResponse): BkashToken {
  const expiresInSeconds = Number(response.expires_in);

  return {
    idToken: response.id_token,
    refreshToken: response.refresh_token,
    tokenType: response.token_type,
    expiresInSeconds,
    expiresAt: Date.now() + expiresInSeconds * 1_000,
  };
}

function compactRequestBody(
  body: Record<string, string | undefined>,
): Record<string, string> {
  return Object.fromEntries(
    Object.entries(body).filter(([, value]) => value !== undefined),
  ) as Record<string, string>;
}

function requireString(value: string | undefined, fieldName: string): void {
  try {
    assertNonEmptyString(value, `${fieldName} is required.`);
  } catch (error) {
    if (error instanceof ValidationError) {
      throw error;
    }

    throw new ValidationError(`${fieldName} is required.`, {
      cause: error,
    });
  }
}

function isRecord(value: unknown): value is Record<string, unknown> {
  return typeof value === "object" && value !== null && !Array.isArray(value);
}